  // TODO: return the count of keys that are new — not already in
  // `seen`, and not a repeat of an earlier key in this same array.
}

items.solution:
function countNewMessages(seen, keys) {
  let count = 0;
  for (const key of keys) {
    if (!seen.has(key)) {
      seen.add(key);
      count++;
    }
  }
  return count;
}

