  // TODO: return the smallest attempt (1-indexed) where
  // baseDelayMs * 2^(attempt-1) >= maxDelayMs.
}

items.solution:
function attemptsUntilCapped(baseDelayMs, maxDelayMs) {
  let attempt = 1;
  while (baseDelayMs * Math.pow(2, attempt - 1) < maxDelayMs) {
    attempt++;
  }
  return attempt;
}

